import{_ as r,o as n,c as t,O as a}from"./chunks/framework.db831a78.js";const c=JSON.parse('{"title":"MySQL","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/05-MySQL.md","filePath":"interview/后端/Java/05-MySQL.md","lastUpdated":1788851914000}'),e={name:"interview/后端/Java/05-MySQL.md"};function s(g,o,i,l,d,p){return n(),t("div",null,o[0]||(o[0]=[a('<h1 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-innodb-与-myisam-区别-★★★" tabindex="-1">1. InnoDB 与 MyISAM 区别 ★★★ <a class="header-anchor" href="#_1-innodb-与-myisam-区别-★★★" aria-label="Permalink to &quot;1. InnoDB 与 MyISAM 区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> InnoDB 支持事务、行级锁、外键、崩溃恢复，索引是聚簇的（数据即索引）；MyISAM 都不支持，只有表级锁、索引和数据分离，但无事务开销所以某些只读查询略快。MySQL 5.5 之后默认就是 InnoDB。一句话：生产一律 InnoDB。</p><p><strong>我的项目关联</strong> 我们全部表都是 InnoDB，没得选——订单、支付、对账这些都要事务，MyISAM 根本不能用。这条基本是送分题，记住「要事务就 InnoDB」即可。</p><p><strong>面试答题话术</strong> 「InnoDB 有事务、行锁、外键、崩溃恢复，索引是聚簇的；MyISAM 没事务、表锁、索引数据分离。MySQL 5.5 之后默认 InnoDB，生产上只要涉及事务就只能 InnoDB，我们项目全是它。」</p><hr><h2 id="_2-索引为什么用-b-树-★★★" tabindex="-1">2. 索引为什么用 B+ 树 ★★★ <a class="header-anchor" href="#_2-索引为什么用-b-树-★★★" aria-label="Permalink to &quot;2. 索引为什么用 B+ 树 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 哈希不支持范围查询和排序；二叉搜索树/红黑树太高，磁盘 IO 次数跟着树高走；B 树每个节点既存索引又存数据，一页能放的索引少，树也高。B+ 树则是「非叶子只存索引、数据全在叶子」，一页能塞更多索引，树更矮（3 层能存千万级）；叶子节点还用双向链表连起来，天然支持范围和排序。</p><p><strong>我的项目关联</strong> 知道「B+ 树矮、叶子有链表、支持范围查询」这个结论就够。我们的查询大量是「按桩编号 + 时间范围查订单」，正好吃 B+ 树范围扫描的红利，这也是为什么时间字段要进联合索引。</p><p><strong>面试答题话术</strong> 「选 B+ 树的核心是磁盘 IO：树越矮 IO 越少。B+ 树非叶子只存索引、能塞更多，所以树矮；数据全在叶子，叶子之间还有链表，范围查询和排序天然支持。哈希不能范围查，二叉树太高。项目里订单按桩加时间范围查，就靠叶子的链表顺序扫。」</p><hr><h2 id="_3-聚簇索引、回表、覆盖索引-★★★" tabindex="-1">3. 聚簇索引、回表、覆盖索引 ★★★ <a class="header-anchor" href="#_3-聚簇索引、回表、覆盖索引-★★★" aria-label="Permalink to &quot;3. 聚簇索引、回表、覆盖索引 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 聚簇索引（主键索引）的叶子存整行数据，一张表只能有一个。二级索引的叶子存「索引列 + 主键值」，所以用它查完还得拿主键回聚簇索引捞整行，这叫回表。如果查的列全在二级索引里，就不用回表，这就是覆盖索引，性能最好。另外主键建议自增：顺序插入减少页分裂，UUID 随机插入会频繁页分裂、出碎片。</p><p><strong>我的项目关联</strong> 优化时最常用的手段就是覆盖索引。比如「按桩编号 + 时间查订单状态」，我把要查的字段一起放进联合索引，就能避免回表。主键我们统一用自增或雪花 ID，不用 UUID，就是防页分裂。<strong>说清楚</strong>：我们没被 UUID 主键搞出过线上事故，这是建表规范上直接禁掉的。</p><p><strong>面试答题话术</strong> 「聚簇索引叶子存整行，二级索引叶子存索引列加主键，所以二级索引查完要回表。查的列都在索引里叫覆盖索引，不用回表，是最常见的优化点。主键建议自增，为的是顺序插入少页分裂，UUID 随机插会频繁分裂。项目里我们流行『把要查的列一起建进联合索引』来避免回表。」</p><hr><h2 id="_4-最左前缀与联合索引-★★★" tabindex="-1">4. 最左前缀与联合索引 ★★★ <a class="header-anchor" href="#_4-最左前缀与联合索引-★★★" aria-label="Permalink to &quot;4. 最左前缀与联合索引 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 联合索引 (a,b,c) 是按 a、b、c 的字典序排的，所以查询必须从最左列连续匹配才能用上索引：(a)、(a,b)、(a,b,c) 能命中；直接查 b、c 不行。还有一点：范围查询会「中断」，<code>a=1 and b&gt;2</code> 用到 a 和 b，但 b 后面的 c 就用不上了，所以范围列尽量往联合索引后面放。</p><p><strong>我的项目关联</strong> 这直接决定我们联合索引的字段顺序：等值条件、区分度高的列放最左，时间范围这种范围查询放最后。比如「桩编号（等值）+ 订单状态（等值）+ 创建时间（范围）」。</p><p><strong>面试答题话术</strong> 「联合索引按最左列顺序排，所以必须从最左连续匹配。范围查询会中断后续列，所以设计时等值条件放前面、范围条件放最后。项目里我们的索引就是这个顺序：桩编号、状态这些等值列在前，时间范围在后。」</p><hr><h2 id="_5-索引失效场景-★★★-【简历亮点-高频追问】" tabindex="-1">5. 索引失效场景 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-索引失效场景-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 索引失效场景 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 常见失效：索引列上做函数或运算（<code>YEAR(create_time)=2024</code>、<code>id+1=5</code>）；隐式类型转换（字符串字段没加引号，比如手机号）；不满足最左前缀；范围查询后面的列；<code>!=</code>、<code>NOT IN</code>；前导模糊 <code>LIKE &#39;%xx&#39;</code>；OR 连了非索引列；数据量特别小时优化器干脆全表扫。</p><p><strong>我的项目关联</strong><strong>隐式类型转换这个坑我们踩过。</strong> 现象是「明明建了索引，查询还是很慢」，排查发现是某个查询把字符串类型的编号当成数字传进去（或者反过来），字段类型和参数类型不一致触发隐式转换，索引直接失效。修复就是保证参数类型和字段类型一致。<strong>这是真实踩过的</strong>，后来我们把「类型必须一致」写进了 SQL review 规范。</p><p><strong>面试答题话术</strong> 「常见失效有：索引列上用函数或运算、隐式类型转换、违反最左前缀、范围后面的列、前导模糊 like %xx、or 连非索引列。我踩过隐式类型转换——字符串编号当数字传，索引直接失效，查询变慢，改回类型一致就好了。判断走没走索引就是 explain 看 type 和 key。」</p><hr><h2 id="_6-explain-关键字段-★★★" tabindex="-1">6. EXPLAIN 关键字段 ★★★ <a class="header-anchor" href="#_6-explain-关键字段-★★★" aria-label="Permalink to &quot;6. EXPLAIN 关键字段 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 重点看四样：type（访问类型，好坏顺序 system &gt; const &gt; eq_ref &gt; ref &gt; range &gt; index &gt; ALL）、key（实际用的索引）、rows（预估扫描行数）、Extra。Extra 里 <code>Using index</code> 是覆盖索引（好），<code>Using filesort</code> 是额外排序（要优化），<code>Using temporary</code> 是用了临时表（group by/distinct 没走索引）。</p><p><strong>我的项目关联</strong> 我日常排查慢 SQL 就是 explain 起手，先看 type 是不是 ALL、再看 Extra 有没有 filesort 或 temporary。看到 ALL 基本就是缺索引或者索引失效了。</p><p><strong>面试答题话术</strong> 「explain 重点看四列：type、key、rows、Extra。type 从好到差是 const、ref、range、index、ALL，看到 ALL 就是全表扫；Extra 里 Using index 是覆盖索引，Using filesort 和 Using temporary 是性能隐患。我排慢 SQL 就是先看 type 和 Extra。」</p><hr><h2 id="_7-事务-acid-及实现原理-★★★" tabindex="-1">7. 事务 ACID 及实现原理 ★★★ <a class="header-anchor" href="#_7-事务-acid-及实现原理-★★★" aria-label="Permalink to &quot;7. 事务 ACID 及实现原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 原子性靠 undo log（能回滚）；持久性靠 redo log（提交后不丢）；隔离性靠锁 + MVCC；一致性是前三个共同保证的结果，不是单独一个机制。redo 记「改了什么」用于崩溃恢复，undo 记「改前的值」用于回滚和 MVCC。</p><p><strong>我的项目关联</strong> 支付、订单、对账这些强一致场景全靠事务兜底。<strong>提醒一点</strong>：事务别写太大——大事务会占锁久、undo 膨胀、还可能拖慢主从，所以我们跑批是分批提交。</p><p><strong>面试答题话术</strong> 「A 靠 undo log，D 靠 redo log，I 靠锁加 MVCC，C 是这三个共同的结果。redo 记改了什么、用于崩溃恢复；undo 记改前的值、用于回滚和 MVCC。项目里事务是我们的底线，但不会写大事务，批量场景分批提交。」</p><hr><h2 id="_8-隔离级别与并发问题-★★★" tabindex="-1">8. 隔离级别与并发问题 ★★★ <a class="header-anchor" href="#_8-隔离级别与并发问题-★★★" aria-label="Permalink to &quot;8. 隔离级别与并发问题 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 三种并发问题：脏读（读到别人没提交的）、不可重复读（同一事务两次读，中间别人 update 了）、幻读（中间别人 insert/delete，行数变了）。四个级别：读未提交（全有）、读已提交 RC（解决脏读）、可重复读 RR（解决脏读+不可重复读，MVCC 下基本解决幻读，MySQL 默认）、串行化（全解决但慢）。Oracle 默认是 RC。</p><p><strong>我的项目关联</strong> 我们用 MySQL 默认的 RR。但要注意：RR 下间隙锁多，并发写容易死锁；所以像对账这种批量更新的场景，反而要控制锁范围、缩短事务。</p><p><strong>面试答题话术</strong> 「三种问题：脏读、不可重复读、幻读。四个级别：读未提交、读已提交、可重复读、串行化。MySQL 默认 RR，靠 MVCC 加间隙锁基本解决幻读；Oracle 默认 RC。这个差异常考。项目里用默认 RR，但批量更新时我会特别小心间隙锁带来的死锁。」</p><hr><h2 id="_9-mvcc-多版本并发控制-★★★-【简历亮点-高频追问】" tabindex="-1">9. MVCC 多版本并发控制 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_9-mvcc-多版本并发控制-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;9. MVCC 多版本并发控制 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> MVCC 让「读不加锁、写不阻塞读」。原理是每行有隐藏列：最近修改的事务 id、指向 undo log 旧版本的回滚指针。读的时候根据 ReadView（快照）判断哪些版本可见，读的是历史版本。RC 和 RR 的区别就在 ReadView：RC 每次 SELECT 都新建一个（所以能看到别人新提交的），RR 是事务内第一次 SELECT 建一次然后复用（所以可重复读）。</p><p><strong>我的项目关联</strong> 理解 MVCC 对我实际有用：为什么我的长事务里读到的还是老数据、为什么长事务会让 undo 链变长拖慢查询——都跟 ReadView 和版本链有关。所以我们规范是<strong>事务尽量短</strong>，尤其别在事务里做远程调用。</p><p><strong>面试答题话术</strong> 「MVCC 是隐藏列加 undo log 加 ReadView，做到读不加锁、读写不阻塞。RC 和 RR 的差别就在 ReadView 的生成时机：RC 每次查都新建，所以能看到别人刚提交的；RR 只在事务第一次查时建一次然后复用，所以可重复读。项目里我特别注意别开长事务，因为长事务会让版本链变长、读变慢。」</p><hr><h2 id="_10-mysql-锁-行锁、间隙锁、临键锁-★★★" tabindex="-1">10. MySQL 锁：行锁、间隙锁、临键锁 ★★★ <a class="header-anchor" href="#_10-mysql-锁-行锁、间隙锁、临键锁-★★★" aria-label="Permalink to &quot;10. MySQL 锁：行锁、间隙锁、临键锁 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> InnoDB 有行锁。记录锁锁单行；间隙锁锁的是「区间之间的空隙」，防止别人往里插；临键锁 = 记录锁 + 间隙锁，锁「左开右闭」的区间，RR 下用来解决幻读。死锁排查用 <code>SHOW ENGINE INNODB STATUS</code> 看 LATEST DETECTED DEADLOCK。</p><p><strong>我的项目关联</strong> 对账、批量更新订单状态时最容易撞间隙锁。我们的做法是：更新条件尽量走主键或唯一索引，把范围锁降成单行锁，减少死锁概率。死锁真发生了 MySQL 会自动回滚一个事务，业务侧做好重试。</p><p><strong>面试答题话术</strong> 「行锁里记录锁锁单行，间隙锁锁空隙防插入，临键锁是两者的结合、锁左开右闭区间，RR 下用来解决幻读。死锁排查看 SHOW ENGINE INNODB STATUS 的 LATEST DETECTED DEADLOCK。项目里批量更新我尽量走主键，缩小锁范围，死锁就让业务重试。」</p><hr><h2 id="_11-三大范式与反范式-★★☆" tabindex="-1">11. 三大范式与反范式 ★★☆ <a class="header-anchor" href="#_11-三大范式与反范式-★★☆" aria-label="Permalink to &quot;11. 三大范式与反范式 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 1NF 列不可再分，2NF 消除部分依赖，3NF 消除传递依赖。反范式就是故意冗余字段（比如订单表冗余桩编号、用户名），用空间换时间、减少 join。</p><p><strong>我的项目关联</strong> 我们是「范式打底 + 关键查询适度冗余」。比如订单表里会冗余一些场站名、桩编号，避免每次都 join 设备表。这是为了查询性能，值得的取舍。</p><p><strong>面试答题话术</strong> 「三大范式解决冗余和依赖问题；反范式是故意冗余，用空间换减少 join。项目里我们是范式打底、关键查询适度冗余，比如订单表冗余场站名，避免 join 设备表。」</p><hr><h2 id="_12-三大日志-redo、undo、binlog-★★★" tabindex="-1">12. 三大日志：redo、undo、binlog ★★★ <a class="header-anchor" href="#_12-三大日志-redo、undo、binlog-★★★" aria-label="Permalink to &quot;12. 三大日志：redo、undo、binlog ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> redo log 是 InnoDB 的物理日志，记「数据页改了什么」，顺序写、循环写，用于崩溃恢复（持久性）。undo log 记「改前的值」，用于回滚和 MVCC。binlog 是 Server 层的逻辑日志，记录所有变更，用于主从复制和数据恢复，是追加写。redo 和 binlog 靠两阶段提交保证一致，不然主从会不一致。binlog 格式主流是 row。</p><p><strong>我的项目关联</strong> 我们做过 binlog 监听同步数据（比如把订单变更同步到搜索或缓存）。知道「redo 是引擎层物理、binlog 是 Server 层逻辑」这个区别，答两阶段提交的时候就顺。</p><p><strong>面试答题话术</strong> 「redo 是 InnoDB 的物理日志、循环写、做崩溃恢复；undo 记改前的值、做回滚和 MVCC；binlog 是 Server 层的逻辑日志、追加写、做主从复制和数据恢复。redo 和 binlog 靠两阶段提交保证一致，不然主从数据会不一致。」</p><hr><h2 id="_13-主从复制原理-★★★" tabindex="-1">13. 主从复制原理 ★★★ <a class="header-anchor" href="#_13-主从复制原理-★★★" aria-label="Permalink to &quot;13. 主从复制原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 主库写 binlog → 从库 IO 线程拉 binlog 写本地 relay log → 从库 SQL 线程重放 relay log。作用是读写分离、备份、高可用。延迟原因是：从库重放慢（单线程）、有大事务、硬件差、网络慢。</p><p><strong>我的项目关联</strong> 我们做了读写分离，查询走从库、写走主库。<strong>但有个必须注意的点</strong>：写完立刻要读的场景（比如下单后马上查订单），必须强制走主库，不然主从延迟会读到旧数据。这是通用坑，我们用「关键读走主库」来规避。</p><p><strong>面试答题话术</strong> 「主库写 binlog，从库 IO 线程拉过来写 relay log，SQL 线程再重放。延迟主要是从库重放慢和大事务。项目里我们读写分离，但『写完立刻读』的场景强制走主库，不然会读到旧数据。」</p><hr><h2 id="_14-慢查询优化思路-★★★-【简历亮点-高频追问】" tabindex="-1">14. 慢查询优化思路 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_14-慢查询优化思路-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;14. 慢查询优化思路 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 四步走：先用慢查询日志 + EXPLAIN 定位；看 type 是不是 ALL、缺不缺索引；加合适的索引（最左前缀、覆盖索引、避免失效）；再优化 SQL（别 SELECT *、别在索引列上用函数、小表驱动大表）；还不行才上读写分离 / 缓存 / 分库分表。</p><p><strong>我的项目关联</strong> 这个流程我走得比较多。<strong>说明一下现象</strong>：我们遇到过订单列表接口变慢，explain 一看是新增的查询条件没走索引、type 是 ALL，加了联合索引就好了。<strong>这是真实排查过的</strong>，不是纸上谈兵。经验是：先看执行计划，别盲目加缓存。</p><p><strong>面试答题话术</strong> 「四步：慢日志和 explain 定位、看 type 和索引、加索引、优化 SQL。项目里订单列表变慢就是这么查的——explain 发现全表扫，加了联合索引解决。原则是先看执行计划再动手，别上来就加缓存或分表。」</p><hr><h2 id="_15-分库分表-★★☆" tabindex="-1">15. 分库分表 ★★☆ <a class="header-anchor" href="#_15-分库分表-★★☆" aria-label="Permalink to &quot;15. 分库分表 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 垂直拆：按业务拆库（订单库、用户库）、按列拆表（冷热字段）。水平拆：按行分，id 哈希或范围分到多表多库。中间件用 ShardingSphere。带来的问题：分布式主键（雪花）、跨库 join、分布式事务、路由。</p><p><strong>我的项目关联</strong> 目前我们订单量还没到必须先分表的程度，优先做的是索引优化 + 冷热分离 + 归档。<strong>这条属于了解即可</strong>：真到单表千万级、单库有瓶颈了才考虑，顺序是「索引 → 缓存 → 读写分离 → 分表」。</p><p><strong>面试答题话术</strong> 「分库分表分垂直和水平，垂直按业务或字段拆，水平按行分。中间件一般用 ShardingSphere。但这是最后手段，顺序是索引优化、缓存、读写分离，都不行了才分。项目里我们现在靠索引加冷热归档，还没到分表。」</p><hr><h2 id="_16-大表如何优化-★★★" tabindex="-1">16. 大表如何优化 ★★★ <a class="header-anchor" href="#_16-大表如何优化-★★★" aria-label="Permalink to &quot;16. 大表如何优化 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 索引优化、覆盖索引避免回表；冷热数据分离、历史数据归档；读写分离 + 缓存热点；再往后是垂直/水平拆分；最后才考虑换列式存储/大数据引擎。</p><p><strong>我的项目关联</strong> 充电订单和历史流水是典型的大表。我们的做法：近期订单留 MySQL（热），历史订单归档到冷库或者 ClickHouse（冷），查询走对应数据源。这样主表一直保持比较小。</p><p><strong>面试答题话术</strong> 「大表优化从轻到重：先索引和覆盖索引，再冷热分离和归档，然后是读写分离加缓存，最后才分库分表。项目里充电订单就是这么做的——近期数据留 MySQL，历史归档到 ClickHouse，主表保持小。」</p><hr><h2 id="_17-sql-执行顺序-★★☆" tabindex="-1">17. SQL 执行顺序 ★★☆ <a class="header-anchor" href="#_17-sql-执行顺序-★★☆" aria-label="Permalink to &quot;17. SQL 执行顺序 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> FROM → JOIN/ON → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT。记住它，才不会写错 SQL：WHERE 在分组前所以不能用聚合函数，聚合条件得用 HAVING；SELECT 的别名在 WHERE 里不能用，因为它比 SELECT 晚执行。</p><p><strong>我的项目关联</strong> 结论够用。实际写统计 SQL 时靠它判断条件该放 WHERE 还是 HAVING。</p><p><strong>面试答题话术</strong> 「顺序是 FROM、JOIN、WHERE、GROUP BY、HAVING、SELECT、DISTINCT、ORDER BY、LIMIT。两个易错点：WHERE 不能用聚合函数要用 HAVING；SELECT 的别名在 WHERE 里用不了，因为它执行得晚。」</p><hr><h2 id="_18-索引下推-icp-★★★" tabindex="-1">18. 索引下推（ICP）★★★ <a class="header-anchor" href="#_18-索引下推-icp-★★★" aria-label="Permalink to &quot;18. 索引下推（ICP）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> MySQL 5.6 的优化：把「能在索引层判断的条件」下推到存储引擎层过滤，减少回表次数。例：联合索引 (name, age) 查 <code>name like &#39;张%&#39; and age=20</code>，没 ICP 是先把所有「张」开头的都回表、再在 Server 层过滤 age；有 ICP 就直接在索引层用 age 过滤，只有两条都满足的才回表。</p><p><strong>我的项目关联</strong> 知道「ICP 减少回表」这个结论就够。它解释了为什么「联合索引里带上过滤字段」能加速——因为可以在索引层就过滤掉大部分数据。</p><p><strong>面试答题话术</strong> 「ICP 是把能下推的过滤条件推到存储引擎层，在索引里就把不满足的过滤掉，减少回表。只对二级索引生效，条件是函数或运算就不下推。项目里体现就是：把常用过滤字段一起放进联合索引，能让 ICP 帮忙减少回表。」</p><hr><h2 id="_19-索引设计原则-★★★" tabindex="-1">19. 索引设计原则 ★★★ <a class="header-anchor" href="#_19-索引设计原则-★★★" aria-label="Permalink to &quot;19. 索引设计原则 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 选区分度高的列；为 WHERE、ORDER BY、GROUP BY、JOIN 的列建索引；联合索引按最左前缀、等值列在前；尽量做覆盖索引；索引别建太多（拖慢写入）；长字符串用前缀索引；主键用自增。区分度极低的列（性别、状态枚举）单独建索引没意义。</p><p><strong>我的项目关联</strong> 我们建索引基本围绕「查询模式」来：订单按桩编号 + 状态 + 时间查，就建对应的联合索引。状态这种低区分度列不单独建，而是放在联合索引里起过滤作用。</p><p><strong>面试答题话术</strong> 「原则就是：围绕 where、order by、join 建索引；联合索引等值列在前、区分度高的在前；尽量覆盖索引；控制数量因为拖慢写入。低区分度的列像状态、性别不单独建索引，放联合索引里当过滤列就行。项目里索引都是按实际查询模式设计的。」</p><hr><h2 id="_20-如何优化表结构-★★☆" tabindex="-1">20. 如何优化表结构 ★★☆ <a class="header-anchor" href="#_20-如何优化表结构-★★☆" aria-label="Permalink to &quot;20. 如何优化表结构 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 字段类型够用就行（能用 int 不用 varchar）；尽量 NOT NULL 给默认值；大字段（TEXT/BLOB）拆到扩展表，别撑大主表；范式打底 + 适度反范式。</p><p><strong>我的项目关联</strong> 我们建表规范里有两条：状态、类型这种用 tinyint 而不是 varchar；报文原文这种大字段单独放扩展表，主表不存，避免拖慢查询。</p><p><strong>面试答题话术</strong> 「字段类型选够用的最小类型，尽量 NOT NULL，大字段拆到独立表。项目里状态类型用 tinyint，报文原文这种大字段单独一张表，主表保持轻。」</p><hr><h2 id="_21-mysql-如何避免死锁-★★★" tabindex="-1">21. MySQL 如何避免死锁 ★★★ <a class="header-anchor" href="#_21-mysql-如何避免死锁-★★★" aria-label="Permalink to &quot;21. MySQL 如何避免死锁 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 死锁是两个事务按不同顺序加锁、互相等对方。避免手段：按固定顺序访问表和行；尽量用主键/唯一索引定位，缩小锁范围；事务尽量小、尽快提交；一次申请完所需锁；加锁超时和死锁检测。发生死锁时 MySQL 会自动检测并回滚代价小的那个事务。</p><p><strong>我的项目关联</strong> 我们批量更新订单状态时踩过（通用坑）：先按 A 顺序更新、另一个业务按 B 顺序更新，交叉就死锁。解决是按统一顺序处理、并且用主键定位精确到行。MySQL 自动回滚后业务侧重试一次即可。</p><p><strong>面试答题话术</strong> 「避免死锁就几条：统一加锁顺序、用主键精确定位缩小锁范围、事务小且快提交。排查看 SHOW ENGINE INNODB STATUS 的 LATEST DETECTED DEADLOCK。死锁发生后 MySQL 会自动回滚一个事务，业务侧做好重试。项目里批量更新就是统一顺序加主键定位。」</p><hr><h2 id="_22-大量数据插入的性能优化-★★★" tabindex="-1">22. 大量数据插入的性能优化 ★★★ <a class="header-anchor" href="#_22-大量数据插入的性能优化-★★★" aria-label="Permalink to &quot;22. 大量数据插入的性能优化 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 批量插（一条 INSERT 带多个 VALUES）比一条条插快很多——省网络往返、省事务提交、省 SQL 解析。再进一步：<code>autocommit=0</code> 批量提交、<code>LOAD DATA INFILE</code> 导数据、临时关唯一性/外键检查、必要时先关索引导完再重建。</p><p><strong>我的项目关联</strong> 对账、账单生成这种批量写我们用「分批 + 批量 insert」，比如每 500~1000 条一批提交，兼顾速度和事务大小。<strong>注意</strong>：不是越大越好，批次太大就变成大事务，会锁久、undo 膨胀、还可能拖慢主从。</p><p><strong>面试答题话术</strong> 「批量插入快是因为省了网络往返、事务提交、SQL 解析。手段是批量 VALUES、批量提交、LOAD DATA INFILE，必要时导完再重建索引。但批次不能无限大，太大了变大事务，会锁久、拖主从。项目里我们是分批批量插入，每批几百到一千条。」</p><hr><h2 id="_23-大数据量批量写会导致什么问题-★★☆" tabindex="-1">23. 大数据量批量写会导致什么问题 ★★☆ <a class="header-anchor" href="#_23-大数据量批量写会导致什么问题-★★☆" aria-label="Permalink to &quot;23. 大数据量批量写会导致什么问题 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 大事务（undo 膨胀、占锁久、主从延迟）；锁竞争（批量更新锁范围大，容易死锁或长时间阻塞）；binlog 膨胀；主从延迟；随机主键插入还会页分裂。解决就是分批提交、控制批次大小、用顺序主键、避开高峰。</p><p><strong>我的项目关联</strong> 这就是为什么我们坚持分批。跑对账时如果一次性更新几十万行，锁和主从延迟都会出问题，分成小批次提交就稳很多。</p><p><strong>面试答题话术</strong> 「批量写大了会有几个问题：大事务导致 undo 膨胀、占锁久、主从延迟，还有锁竞争和 binlog 膨胀。解决就是分批提交、控制批次大小、顺序主键、避开高峰期。项目里跑批都是分批的。」</p><hr><h2 id="_24-ip-地址如何存数据库-★★☆" tabindex="-1">24. IP 地址如何存数据库 ★★☆ <a class="header-anchor" href="#_24-ip-地址如何存数据库-★★☆" aria-label="Permalink to &quot;24. IP 地址如何存数据库 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> IPv4 推荐用 <code>INT UNSIGNED</code> 存（4 字节），配 <code>INET_ATON()</code>/<code>INET_NTOA()</code> 转换：省空间（比 varchar 短）、比较大小快、IP 段范围查询能走索引。IPv6 是 128 位，用 <code>VARBINARY(16)</code> 配 <code>INET6_ATON()</code>。</p><p><strong>我的项目关联</strong> 我们记录充电桩、网关请求的来源 IP、以及互联互通上报的 IP，就是用整数存 IPv4 的，方便做「某 IP 段」的统计和过滤。这条知道方案就行。</p><p><strong>面试答题话术</strong> 「IPv4 用 INT UNSIGNED 存，配 INET_ATON 和 INET_NTOA 转换，好处是省空间、能比较大小、IP 段范围查询能走索引；IPv6 用 VARBINARY(16)。项目里记录来源 IP 就是这种存法。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li>全局锁/表锁：备份、DDL 场景用，日常业务基本不碰，知道有这三层锁就行。</li><li>分区表：物理上把一张表按时间/范围切分，能提高大表维护效率，但和分表不是一回事。</li></ul>',125)]))}const I=r(e,[["render",s]]);export{c as __pageData,I as default};
